import{_ as o,C as n,c as r,o as l,a3 as e,G as a}from"./chunks/framework.Dokpd4od.js";const _=JSON.parse('{"title":"Portal access","description":"","frontmatter":{},"headers":[],"relativePath":"master/general-settings/users/portal-access.md","filePath":"master/general-settings/users/portal-access.md","lastUpdated":1791902625000}'),c={name:"master/general-settings/users/portal-access.md"};function i(h,t,g,p,d,m){const s=n("ImagePopup");return l(),r("div",null,[t[0]||(t[0]=e('<h1 id="portal-access" tabindex="-1">Portal access <a class="header-anchor" href="#portal-access" aria-label="Permalink to &quot;Portal access&quot;">​</a></h1><p><strong>Portal access</strong> lets a customer sign in to your customer portal. You give access to a single contact. The contact gets an email, sets a password, and can then sign in. You can change the password, send a reset link, or remove the access at any time.</p><blockquote><p><strong>In simple words:</strong> Portal access is a key to the customer portal that you hand to one contact at a time.</p></blockquote><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Portal access needs the <strong>Website</strong> plugin. If you do not see the <strong>Portal Access</strong> button on a contact, check that the plugin is installed. See <a href="./../plugins.html">Plugins</a>.</p></div><h2 id="grant-portal-access" tabindex="-1">Grant portal access <a class="header-anchor" href="#grant-portal-access" aria-label="Permalink to &quot;Grant portal access&quot;">​</a></h2><ol><li>Open the contact. See <a href="./../../getting-started/contacts/contacts.html">Contacts</a>.</li><li>Make sure the contact has an email address. Portal access cannot be granted without one.</li><li>Click the <strong>Portal Access</strong> button at the top of the contact, then click <strong>Grant Portal Access</strong>.</li><li>Read the message in the window. It names the email address that will get the invitation.</li><li>Confirm.</li></ol><p>The contact receives an email with a link to set a password for the customer portal.</p>',7)),a(s,{src:"/images1/general-settings/portal_access_menu.png",alt:"Contact page with the Portal Access button open showing Grant Portal Access"}),a(s,{src:"/images1/general-settings/portal_grant_modal.png",alt:"Grant Portal Access window with the invitation message"}),t[1]||(t[1]=e('<div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Each email address can have portal access only once. If another contact with portal access already uses the same email address, Aureus shows <strong>Email address already in use</strong>.</p></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>If the invitation email cannot be sent, Aureus still grants the access and tells you the email failed. Use <strong>Send Password Reset</strong> to send the link again later.</p></div><div class="info custom-block"><p class="custom-block-title">INFO</p><p>A vendor with portal access can sign in and answer the RFQs you send. See <a href="./../../supply-chain/purchase/orders/vendor-portal.html">Vendor portal</a>.</p></div><h2 id="see-who-has-portal-access" tabindex="-1">See who has portal access <a class="header-anchor" href="#see-who-has-portal-access" aria-label="Permalink to &quot;See who has portal access&quot;">​</a></h2><ul><li>In the contact list, a <strong>Portal Access</strong> badge shows on contacts that have access. You can also filter the list by <strong>Portal Access</strong>.</li><li>On the contact page, the <strong>Customer Portal</strong> section shows: <ul><li><strong><em>Portal Access:</em></strong> <strong>Granted</strong> or <strong>Not Granted</strong>.</li><li><strong><em>Email Verified At:</em></strong> When the contact set a password, or <strong>Never</strong>.</li><li><strong><em>Last Portal Login:</em></strong> The last time the contact signed in, or <strong>Never</strong>.</li></ul></li></ul>',5)),a(s,{src:"/images1/general-settings/portal_status_section.png",alt:"Customer Portal section on a contact page"}),t[2]||(t[2]=e('<h2 id="manage-portal-access" tabindex="-1">Manage portal access <a class="header-anchor" href="#manage-portal-access" aria-label="Permalink to &quot;Manage portal access&quot;">​</a></h2><p>Open the <strong>Portal Access</strong> button on the contact to use these actions:</p><ul><li><strong><em>Change Password:</em></strong> Set a new portal password for the contact. Enter <strong>New Password</strong> and <strong>Confirm New Password</strong>.</li><li><strong><em>Send Password Reset:</em></strong> Email a password reset link to the contact.</li><li><strong><em>Revoke Portal Access:</em></strong> Stop the contact from signing in. Any reset link that is still waiting stops working.</li></ul><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../../getting-started/contacts/contacts.html">Contacts</a></li><li><a href="./users.html">Users</a></li><li><a href="./../../supply-chain/purchase/orders/vendor-portal.html">Vendor portal</a></li><li><a href="./../../website/customers/portal-and-sign-in.html">Website customers and sign in</a></li></ul>',5))])}const P=o(c,[["render",i]]);export{_ as __pageData,P as default};
